using Ginecologia.Modules.Autorizacion.Api;
using Ginecologia.Modules.ConsultaMedica.Application;
using Ginecologia.Modules.ConsultaMedica.Domain;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
namespace Ginecologia.Modules.ConsultaMedica.Api;
public sealed record CreateConsultaRequest(Guid PatientId, DateOnly Fecha);
public sealed record PrescriptionItemRequest(int Orden,string Medicamento,string Dosis,string Via,string Frecuencia,string DuracionTexto);
public sealed record UpdateConsultaRequest(int? PresionSistolica,int? PresionDiastolica,decimal? PesoKg,decimal? TallaCm,DateOnly? Fum,string MotivoConsulta,string? PadecimientoActual,string? HallazgosMamas,string? HallazgosCervixGenitales,string? HallazgosTactoBimanual,decimal? UltrasonidoEndometrioMm,string? UltrasonidoOvarioDerecho,string? UltrasonidoOvarioIzquierdo,string? UltrasonidoSacoGestacionalEmbrion,string? DiagnosticoCie,string? DiagnosticoDescripcion,string? EstudiosSolicitados,string? IndicacionesProximaCita,IReadOnlyList<PrescriptionItemRequest> PrescriptionItems);
public static class ConsultaMedicaEndpoints
{ public static IEndpointRouteBuilder MapConsultaMedicaEndpoints(this IEndpointRouteBuilder e) { var g=e.MapGroup("/api/consultas").RequireAuthorization();g.MapGet("/cie10",SearchCie10);g.MapGet("/adjuntos/{attachmentId:guid}/contenido",GetAttachmentContent);g.MapGet("/{id:guid}/receta-pdf",ExportPrescriptionPdf);g.MapGet("/{id:guid}/adjuntos",ListAttachments);g.MapGet("/{id:guid}",Get);g.MapGet("/",List);g.MapPost("/",Create).RequireAuthorization(p=>p.AddRequirements(new PermissionRequirement("consultas.gestionar")));g.MapPut("/{id:guid}",Update).RequireAuthorization(p=>p.AddRequirements(new PermissionRequirement("consultas.gestionar")));g.MapPost("/{id:guid}/finalizar",FinalizeAsync).RequireAuthorization(p=>p.AddRequirements(new PermissionRequirement("consultas.gestionar")));g.MapPost("/{id:guid}/adjuntos",UploadAttachment).RequireAuthorization(p=>p.AddRequirements(new PermissionRequirement("consultas.gestionar")));g.MapDelete("/adjuntos/{attachmentId:guid}",DeleteAttachment).RequireAuthorization(p=>p.AddRequirements(new PermissionRequirement("consultas.gestionar")));return e; }
private static IResult SearchCie10(string? search) { var q=Cie10Catalog.Entries.AsEnumerable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Codigo.Contains(search,StringComparison.OrdinalIgnoreCase)||x.Descripcion.Contains(search,StringComparison.OrdinalIgnoreCase));return Results.Ok(q); }
private static async Task<IResult> Create(CreateConsultaRequest r,HttpContext h,CreateConsultaUseCase u,CancellationToken ct) { if(!Guid.TryParse(h.User.FindFirst("sub")?.Value,out var id))return Results.Unauthorized();try { var c=await u.ExecuteAsync(r.PatientId,r.Fecha,id,ct);return Results.Created($"/api/consultas/{c.Id}",c); }catch(ArgumentException x){return Results.BadRequest(new{message=x.Message});} }
private static async Task<IResult> Update(Guid id,UpdateConsultaRequest r,UpdateConsultaUseCase u,CancellationToken ct) { try { return Results.Ok(await u.ExecuteAsync(id,new(r.PresionSistolica,r.PresionDiastolica,r.PesoKg,r.TallaCm,r.Fum,r.MotivoConsulta,r.PadecimientoActual,r.HallazgosMamas,r.HallazgosCervixGenitales,r.HallazgosTactoBimanual,r.UltrasonidoEndometrioMm,r.UltrasonidoOvarioDerecho,r.UltrasonidoOvarioIzquierdo,r.UltrasonidoSacoGestacionalEmbrion,r.DiagnosticoCie,r.DiagnosticoDescripcion,r.EstudiosSolicitados,r.IndicacionesProximaCita,r.PrescriptionItems.Select(x=>new PrescriptionItemInput(x.Orden,x.Medicamento,x.Dosis,x.Via,x.Frecuencia,x.DuracionTexto)).ToList()),ct)); }catch(ConsultaNotFoundException){return Results.NotFound();}catch(ConsultaFinalizadaException x){return Results.Conflict(new{message=x.Message});}catch(ArgumentException x){return Results.BadRequest(new{message=x.Message});} }
private static async Task<IResult> FinalizeAsync(Guid id,FinalizeConsultaUseCase u,CancellationToken ct) { try{return Results.Ok(await u.ExecuteAsync(id,ct));}catch(ConsultaNotFoundException){return Results.NotFound();}catch(ConsultaFinalizadaException x){return Results.Conflict(new{message=x.Message});} }
private static async Task<IResult> Get(Guid id,GetConsultaUseCase u,CancellationToken ct) { var c=await u.ExecuteAsync(id,ct);return c is null?Results.NotFound():Results.Ok(c); }
private static async Task<IResult> List(Guid patientId,ListConsultasUseCase u,CancellationToken ct,int page=1,int pageSize=20) { try{return Results.Ok(await u.ExecuteAsync(patientId,page,pageSize,ct));}catch(ArgumentException x){return Results.BadRequest(new{message=x.Message});} }
private static async Task<IResult> UploadAttachment(Guid id,HttpRequest r,UploadConsultaAttachmentUseCase u,CancellationToken ct) { var f=(await r.ReadFormAsync(ct)).Files["archivo"];if(f is null)return Results.BadRequest(new{message="Debe adjuntar un archivo."});await using var s=new MemoryStream();await f.CopyToAsync(s,ct);try {var a=await u.ExecuteAsync(id,f.FileName,f.ContentType,s.ToArray(),ct);return Results.Created($"/api/consultas/adjuntos/{a.Id}",a);}catch(ConsultaNotFoundException){return Results.NotFound();}catch(ConsultaFinalizadaException x){return Results.Conflict(new{message=x.Message});}catch(ArgumentException x){return Results.BadRequest(new{message=x.Message});} }
private static async Task<IResult> ListAttachments(Guid id,GetConsultaUseCase u,CancellationToken ct) { var c=await u.ExecuteAsync(id,ct);return c is null?Results.NotFound():Results.Ok(c.Attachments); }
private static async Task<IResult> GetAttachmentContent(Guid attachmentId,GetConsultaAttachmentContentUseCase u,CancellationToken ct) { var a=await u.ExecuteAsync(attachmentId,ct);return a is null?Results.NotFound():Results.File(a.Value.Content,a.Value.Type); }
private static async Task<IResult> DeleteAttachment(Guid attachmentId,DeleteConsultaAttachmentUseCase u,CancellationToken ct) { try{await u.ExecuteAsync(attachmentId,ct);return Results.NoContent();}catch(KeyNotFoundException){return Results.NotFound();}catch(ConsultaFinalizadaException x){return Results.Conflict(new{message=x.Message});} }
private static async Task<IResult> ExportPrescriptionPdf(Guid id,ExportConsultaPrescriptionPdfUseCase u,CancellationToken ct) { try {var pdf=await u.ExecuteAsync(id,ct);return Results.File(pdf.File,"application/pdf",pdf.FileName);}catch(ConsultaNotFoundException){return Results.NotFound();}catch(ArgumentException x){return Results.BadRequest(new{message=x.Message});} }
}
